# Olex Sales: finding businesses (Serper, Companies House, OpenStreetMap, pasted), reading their sites for signals and
# published emails, UK law (limited companies only), drafting (rules checked by code), approving, sending safely
# (address required, warm-up, office hours, spacing, footer, do-not-contact), and the admin screen. tests/sales/mock.mjs.
import json, sys, urllib.request
from playwright.sync_api import sync_playwright
exec(open('tests/meet/e2e.py').read().split("OWNER, EDITOR = ")[0])            # helpers: session, req, sql, check, APP, SHOTS
OWNER, EDITOR = session('owner@test.local'), session('editor@test.local')
SECRET = 'test-cron-secret-0123456789'
def api(body, who=None): return req('/admin/api/sales', body, OWNER if who is None else who)
def ctl(body): urllib.request.urlopen(urllib.request.Request('http://localhost:4570/control', data=json.dumps(body).encode(), headers={'Content-Type': 'application/json'}))
def mlog(kind=None): l = json.loads(urllib.request.urlopen('http://localhost:4570/log').read()); return [x for x in l if not kind or x['kind'] == kind]
def cron(): urllib.request.urlopen(urllib.request.Request(APP + '/api/assistant/cron?run=due', headers={'authorization': 'Bearer ' + SECRET}), timeout=120).read()
def company(name): return json.loads(sql(f"select row_to_json(x) from (select c.*, (select string_agg(code, ',' order by code) from sales_signals s where s.company_id = c.id) as sigs, (select string_agg(email || ':' || email_status, ',') from sales_contacts k where k.company_id = c.id) as emails from sales_companies c where name = '{name}') x"))
sql("delete from sales_outbox; delete from sales_contacts; delete from sales_signals; delete from sales_companies; delete from sales_dnc; update sales_settings set enabled = false, postal_address = null, start_date = null, daily_cap = 20, require_approval = true")
ctl({'reset': True, 'ai': 'good'})

print('Finding businesses')
s, j = api({'action': 'find', 'source': 'serper', 'kind': 'dentist', 'town': 'Austin TX', 'country': 'US'})
check(s == 200 and j['found'] == 6 and j['added'] == 6, f'map listings (Serper): {j}')
check(mlog('serper-places')[0] == {'kind': 'serper-places', 'q': 'dentist in Austin TX', 'gl': 'us'}, 'searched “dentist in Austin TX” in the US')
check(company('On Yelp Only')['domain'] is None, 'a directory page (Yelp) isn’t taken as the business’s own website')
s, j = api({'action': 'find', 'source': 'companies_house', 'kind': 'accounting', 'town': 'Leeds'})
check(s == 200 and j['added'] == 1 and company('Ledger Accountants Limited')['company_type'] == 'ltd', 'Companies House: only the limited company is kept (not the partnership)')
s, j = api({'action': 'find', 'source': 'osm', 'kind': 'cafe', 'town': 'York', 'country': 'GB'}); check(s == 200 and j['added'] == 1, 'OpenStreetMap: a York café')
s, j = api({'action': 'find', 'source': 'manual', 'country': 'US', 'text': 'Old Salon, old-salon.test\nFresh Bakery, , Denver'})
check(j['found'] == 2 and j['added'] == 1, 'a pasted list: a business already known by its website isn’t added twice')
s, j = api({'action': 'find', 'source': 'companies_house', 'kind': 'nope', 'town': 'x'}); check(s == 400, 'unknown kinds are refused')

print('Reading their websites')
for (cid,) in [r.split('|') for r in sql("select id from sales_companies order by id").split('\n')]:
    api({'action': 'profile', 'id': int(cid)})
d = company('Bright Smiles Dental')
check(d['status'] == 'qualified' and d['sigs'] == 'NO_BOOKING,SLOW_MOBILE' and d['emails'] == 'info@slow-dentist.test:deliverable', 'Bright Smiles: slow on phones + no online booking; the email found on its contact page')
check('28/100' in sql(f"select evidence from sales_signals where company_id = {d['id']} and code = 'SLOW_MOBILE'"), 'with Google PageSpeed’s evidence: ' + sql(f"select evidence from sales_signals where company_id = {d['id']} and code = 'SLOW_MOBILE'"))
o = company('Old Salon'); check(o['status'] == 'qualified' and 'NOT_MOBILE' in o['sigs'] and 'OLD_COPYRIGHT' in o['sigs'], 'Old Salon: no mobile layout and “© 2019”: ' + o['sigs'])
m = company('Modern Clinic'); check(m['status'] == 'skipped' and 'Nothing to improve' in m['profile_error'], 'Modern Clinic (fast, mobile, online booking): skipped, with the reason')
n = company('Nomx Cafe'); check(n['status'] == 'no_email' and n['emails'] == 'hi@nomx-cafe.test:invalid', 'an email whose domain can’t receive mail isn’t used')
b = company('No Site Barbers'); check(b['sigs'] == 'NO_WEBSITE' and b['status'] == 'no_email' and '512-555-0199' in b['profile_error'], 'no website: recorded, with its phone number for you')
l = company('Ledger Accountants Limited'); check(l['domain'] == 'nohttps-ledger.test' and 'NO_HTTPS' in l['sigs'] and l['status'] == 'qualified', 'UK limited company: website found by search (the register’s page skipped), no padlock, ready')
c = company('Corner Cafe'); check(c['status'] == 'uk_unconfirmed' and 'limited companies' in c['profile_error'], 'a UK café Companies House can’t confirm as a limited company is NOT emailed (UK law)')

print('Drafting')
s, j = api({'action': 'draft', 'id': d['id']}); m1 = j.get('id')
check(s == 200 and m1, 'a first email is drafted for Bright Smiles')
row = json.loads(sql(f"select row_to_json(o) from sales_outbox o where id = {m1}"))
check(row['status'] == 'waiting' and row['body'].endswith('Olaitan\nOlexweb') and 'https' not in row['body'], 'it waits for your approval, signed “Olaitan / Olexweb”, with no links')
p = mlog('ai')[-1]['prompt']; sysm = mlog('ai')[-1]['system']; check('slow on phones' in p and 'book online' in p and 'Never invent' in sysm, 'the AI got only the real facts, and was told never to invent')
ctl({'ai': 'badThenGood'}); s, j = api({'action': 'draft', 'id': l['id']}); check(s == 200 and len(mlog('ai')) == 3 and 'Your last draft had problems' in mlog('ai')[-1]['prompt'], 'a draft that breaks the rules (link, “hope this finds you well”, fake “Re:”) is rewritten automatically')
ctl({'ai': 'bad'}); s, j = api({'action': 'draft', 'id': o['id']}); o = company('Old Salon')
check(s == 400 and o['status'] == 'write_failed' and 'contains a link' in o['profile_error'], 'if it keeps breaking them, nothing reaches your outbox, and you see why')
ctl({'ai': 'good'})
s, j = api({'action': 'edit', 'id': m1, 'subject': 'hello', 'body': 'Visit https://olexweb.com now\n\nOlaitan\nOlexweb'}); check(s == 400 and 'breaks a rule' in j['error'], 'your own edits are checked too (you can still save anyway)')

print('Sending (only when it’s safe)')
s, o2 = api({'action': 'overview'}); check(o2['blocked'] and 'switched off' in o2['blocked'], 'nothing sends while Olex Sales is off')
api({'action': 'settings', 'settings': {'enabled': True, 'require_approval': True, 'daily_cap': 20, 'sender_name': 'Olaitan Adebayo', 'opt_out_line': 'Not interested? Reply "no thanks" and I won\'t email again.'}})
s, o2 = api({'action': 'overview'}); check('postal address' in (o2['blocked'] or ''), 'nothing sends without your postal address: “' + str(o2['blocked']) + '”')
api({'action': 'approve', 'id': m1}); cron(); check(not mlog('gmail'), 'even approved, it waits until the address is added')
api({'action': 'settings', 'settings': {'enabled': True, 'daily_cap': 20, 'sender_name': 'Olaitan Adebayo', 'postal_address': '12 Example Street\nIkeja, Lagos, Nigeria', 'start_date': '2026-11-10', 'opt_out_line': 'Not interested? Reply "no thanks" and I won\'t email again.'}})
s, o2 = api({'action': 'overview'}); check(o2['blocked'] is None and o2['capToday'] == 5, 'warm-up: 5 a day on day one')
sql("update sales_settings set start_date = '2026-10-31'"); s, o2 = api({'action': 'overview'}); check(o2['capToday'] == 15, 'ten days in: 15 a day')
sql("update sales_settings set start_date = '2026-01-01'"); s, o2 = api({'action': 'overview'}); check(o2['capToday'] == 20, 'never more than your cap of 20')
cron(); g = mlog('gmail')
check(len(g) == 1 and g[0]['to'] == 'info@slow-dentist.test' and g[0]['from'] == 'Olaitan Adebayo <outreach@test.local>', 'it sends from your outreach Gmail, in their office hours')
check(g[0]['text'].startswith('Hi') and 'Not interested? Reply "no thanks"' in g[0]['text'] and '12 Example Street, Ikeja, Lagos, Nigeria' in g[0]['text'], 'with the opt-out line and your postal address (US law)')
check(company('Bright Smiles Dental')['status'] == 'contacted', 'the business is marked as emailed')
m2 = sql(f"select id from sales_outbox where company_id = {l['id']}"); api({'action': 'approve', 'id': int(m2)}); cron()
check(len(mlog('gmail')) == 1, 'a second email waits: one email every 12 minutes at most')
sql("update sales_outbox set sent_at = sent_at - interval '13 minutes' where status = 'sent'"); cron(); g = mlog('gmail')
check(len(g) == 2 and g[1]['to'] == 'enquiries@nohttps-ledger.test', '13 minutes later, the UK one goes out')
api({'action': 'profile', 'id': o['id']}); s, j = api({'action': 'draft', 'id': o['id']}); api({'action': 'approve', 'id': j['id']})
s, x = api({'action': 'dnc-add', 'entry': 'https://www.old-salon.test/about'})
check(s == 200 and sql(f"select status from sales_outbox where id = {j['id']}") == 'cancelled', 'adding a business to “never contact” cancels its waiting email (a pasted link counts as its website)')
s, x = api({'action': 'dnc-add', 'entry': 'not a thing'}); check(s == 400, 'nonsense entries are refused')

print('Who can use it')
s, x = api({'action': 'overview'}, EDITOR); check(s == 403, 'an editor can’t')
s, x = req('/admin/api/sales', {'action': 'overview'}); check(s == 401, 'nobody signed out can')

print('On screen')
with sync_playwright() as pw:
    br = pw.chromium.launch(); cx = br.new_context(viewport={'width': 1280, 'height': 900})
    cx.add_cookies([{'name': '__Host-olex_sess', 'value': OWNER, 'domain': 'localhost', 'path': '/', 'secure': True, 'httpOnly': True, 'sameSite': 'Strict'}])
    P = cx.new_page(); errs = []; P.on('pageerror', lambda e: errs.append(str(e)[:90]))
    P.goto(APP + '/admin/sales#outbox'); P.wait_for_selector('.sl-tabs', timeout=10000)   # the detailed screen (Simple is the default since Install 18)
    check(P.locator('.side-nav a:has-text("Sales")').count() == 1, 'Sales is in the sidebar')
    P.click('.sl-sub button:has-text("Sent and done")'); P.wait_for_selector('.sl-m', timeout=8000)
    check(P.locator('.sl-m').count() >= 2 and P.locator('.sl-sigs span:has-text("Slow on phones")').count() >= 1, 'sent emails show with the evidence they were based on')
    P.click('.sl-tabs button:has-text("Companies")'); P.select_option('.sl-filter select', ''); P.wait_for_selector('.mg-list li', timeout=8000)
    check(P.locator('.mg-list li:has-text("UK: not confirmed")').count() == 1, 'the Companies tab shows each business’s status and reason')
    P.screenshot(path=SHOTS + '/30-sales-companies.png', full_page=True)
    P.click('.sl-tabs button:has-text("Settings")'); P.wait_for_selector('.sl-keys li', timeout=8000)
    check(P.locator('.sl-keys li.on').count() >= 3, 'Settings shows which keys are connected')
    P.screenshot(path=SHOTS + '/31-sales-settings.png', full_page=True)
    check(not errs, 'no page errors', errs); br.close()
print(f'\n{passed} passed, {failed} failed')
sys.exit(1 if failed else 0)
